    RoadSignInfo("3.36", "Стоянку заборонено в непарні числа місяця", "Стоянка на цьому боці дороги заборонена в непарні числа."),
    RoadSignInfo("3.37", "Стоянку заборонено в парні числа місяця", "Стоянка на цьому боці дороги заборонена в парні числа."),
    RoadSignInfo("3.38", "Зона обмеженої стоянки", "Територія, де тривалість стоянки обмежена (незалежно від плати). Час і умови — на знаку або табличках 7.4, 7.19."),
    RoadSignInfo("3.39", "Кінець зони обмеженої стоянки", "Виїзд із зони, позначеної знаком 3.38."),
    RoadSignInfo("3.40", "Митниця", "Заборонено проїжджати без зупинки біля митниці."),
    RoadSignInfo("3.41", "Контроль", "Заборонено проїжджати без зупинки повз контрольний пункт: пост поліції, карантинний чи прикордонний пост, пункт оплати платної дороги."),
    RoadSignInfo("3.42", "Кінець усіх заборон і обмежень", "Одночасно скасовує дію знаків 3.20, 3.25, 3.27, 3.29, 3.33–3.37."),
    RoadSignInfo("3.43", "Небезпека", "Рух усіх учасників заборонено через ДТП, аварію, стихійне лихо чи іншу небезпеку (зсув, повінь, снігопад)."),

    // ---- 4. Наказові -----------------------------------------------------------------
    RoadSignInfo("4.1", "Рух прямо", "Дозволено рух лише прямо. Поворот праворуч у двори та на прилеглі території не заборонено. Не діє на маршрутний транспорт."),
    RoadSignInfo("4.2", "Рух праворуч", "Дозволено рух лише праворуч."),
    RoadSignInfo("4.3", "Рух ліворуч", "Дозволено рух лише ліворуч. Розворот також дозволений."),
    RoadSignInfo("4.4", "Рух прямо або праворуч", "Дозволено рух лише прямо або праворуч."),
    RoadSignInfo("4.5", "Рух прямо або ліворуч", "Дозволено рух прямо або ліворуч. Розворот також дозволений."),
    RoadSignInfo("4.6", "Рух праворуч або ліворуч", "Дозволено рух лише праворуч або ліворуч. Розворот також дозволений."),
    RoadSignInfo("4.7", "Об’їзд перешкоди з правого боку", "Перешкоду можна об’їхати лише праворуч."),
    RoadSignInfo("4.8", "Об’їзд перешкоди з лівого боку", "Перешкоду можна об’їхати лише ліворуч."),
    RoadSignInfo("4.9", "Об’їзд перешкоди з правого або лівого боку", "Перешкоду можна об’їхати з будь-якого боку."),
    RoadSignInfo("4.10", "Круговий рух", "Рух по колу навколо центрального острівця в напрямку стрілок, тобто проти годинникової стрілки."),
    RoadSignInfo("4.11", "Рух легкових автомобілів", "Дозволено рух лише легковим автомобілям, автобусам, мотоциклам, маршрутному транспорту та вантажівкам до 3,5 т."),
    RoadSignInfo("4.12", "Доріжка для велосипедистів", "Рух лише на велосипедах. Якщо немає тротуару чи пішохідної доріжки, тут можуть іти й пішоходи."),
    RoadSignInfo("4.13", "Доріжка для пішоходів", "Рух лише пішоходів."),
    RoadSignInfo("4.14", "Доріжка для пішоходів і велосипедистів", "Спільна доріжка для пішоходів і велосипедистів."),
    RoadSignInfo("4.15", "Доріжка для вершників", "Рух лише вершників."),
    RoadSignInfo("4.16", "Обмеження мінімальної швидкості", "Їдьте не повільніше, ніж вказано на знаку, але й не швидше дозволеного Правилами."),
    RoadSignInfo("4.17", "Кінець обмеження мінімальної швидкості", "Скасовує обмеження мінімальної швидкості, введене знаком 4.16."),
    RoadSignInfo("4.18.1", "Напрямок руху транспортних засобів з небезпечними вантажами", "Транспорту з небезпечними вантажами дозволено рух лише прямо."),
    RoadSignInfo("4.18.2", "Напрямок руху транспортних засобів з небезпечними вантажами", "Транспорту з небезпечними вантажами дозволено рух лише праворуч."),
    RoadSignInfo("4.18.3", "Напрямок руху транспортних засобів з небезпечними вантажами", "Транспорту з небезпечними вантажами дозволено рух лише ліворуч."),

    // ---- 5. Інформаційно-вказівні --------------------------------------------------------
    RoadSignInfo("5.1", "Автомагістраль", "Початок автомагістралі: діють особливі умови розділу 27 (не можна пішоходам, тракторам, розвертатися, зупинятися поза стоянками тощо). Максимум 130 км/год."),
    RoadSignInfo("5.2", "Кінець автомагістралі", "Закінчення автомагістралі."),
    RoadSignInfo("5.3", "Дорога для автомобілів", "Дорога з особливими умовами розділу 27, крім пункту 27.3."),
    RoadSignInfo("5.4", "Кінець дороги для автомобілів", "Закінчення дороги для автомобілів."),
    RoadSignInfo("5.5", "Дорога з одностороннім рухом", "На всій ширині дороги рух лише в одному напрямку."),
    RoadSignInfo("5.6", "Кінець дороги з одностороннім рухом", "Далі починається двосторонній рух."),
    RoadSignInfo("5.7.1", "Виїзд на дорогу з одностороннім рухом", "На перехрещуваній дорозі односторонній рух праворуч: повертати можна лише в напрямку стрілки."),
    RoadSignInfo("5.7.2", "Виїзд на дорогу з одностороннім рухом", "На перехрещуваній дорозі односторонній рух ліворуч."),
    RoadSignInfo("5.8", "Дорога із смугою для руху маршрутних транспортних засобів", "Маршрутний транспорт їде своєю смугою назустріч загальному потоку."),
    RoadSignInfo("5.9", "Кінець дороги із смугою для руху маршрутних транспортних засобів", "Закінчення такої дороги."),
    RoadSignInfo("5.10.1", "Виїзд на дорогу із смугою для руху маршрутних транспортних засобів", "Попереджає, що на дорозі, куди ви виїжджаєте, є зустрічна смуга для маршрутного транспорту (праворуч)."),
    RoadSignInfo("5.10.2", "Виїзд на дорогу із смугою для руху маршрутних транспортних засобів", "Те саме, при виїзді ліворуч."),
    RoadSignInfo("5.11", "Смуга для руху маршрутних транспортних засобів", "Смуга лише для маршрутного транспорту, що їде в попутному напрямку. Інші можуть заїжджати на неї лише для повороту праворуч, якщо смуга відокремлена переривчастою лінією."),
    RoadSignInfo("5.12", "Кінець смуги для руху маршрутних транспортних засобів", "Смуга для маршрутного транспорту закінчується."),
    RoadSignInfo("5.13", "Дорога з реверсивним рухом", "На одній або кількох смугах напрямок руху може змінюватися на протилежний (керують реверсивні світлофори)."),
    RoadSignInfo("5.14", "Кінець дороги з реверсивним рухом", "Ділянка з реверсивним рухом закінчується."),
    RoadSignInfo("5.15", "Виїзд на дорогу з реверсивним рухом", "Попереджає, що на дорозі, куди ви виїжджаєте, організовано реверсивний рух."),
    RoadSignInfo("5.16", "Напрямки руху по смугах", "Показує, куди можна їхати з кожної смуги на перехресті. Ліворуч із крайньої лівої — можна й розвернутися."),
    RoadSignInfo("5.17.1", "Напрямок руху по смугах", "Кількість смуг у кожному напрямку на дорозі з трьома і більше смугами."),
    RoadSignInfo("5.17.2", "Напрямок руху по смугах", "Те саме, з іншим розподілом смуг (може бути змінним при реверсивному русі)."),
    RoadSignInfo("5.18", "Напрямок руху по смузі", "Показує дозволений напрямок руху для однієї смуги."),
    RoadSignInfo("5.19", "Використання смуги руху", "Смуга призначена лише для певних видів транспорту (наприклад, маршрутних) у вказаних напрямках."),
    RoadSignInfo("5.20.1", "Початок додаткової смуги руху", "Праворуч з’являється додаткова смуга (на підйомі або смуга гальмування)."),
    RoadSignInfo("5.20.2", "Початок додаткової смуги руху", "Додаткова смуга, а на основній вказана мінімальна швидкість (4.16): якщо їдете повільніше — перестройтеся праворуч."),
    RoadSignInfo("5.20.3", "Початок додаткової смуги руху", "Ліворуч з’являється смуга для повороту ліворуч або розвороту."),
    RoadSignInfo("5.21.1", "Кінець додаткової смуги руху", "Додаткова смуга чи смуга розгону праворуч закінчується — перестройтеся."),
    RoadSignInfo("5.21.2", "Кінець додаткової смуги руху", "Ліва смуга, призначена для цього напрямку, закінчується."),
    RoadSignInfo("5.22", "Прилягання смуги для розгону транспортних засобів", "Справа на одному рівні до основної смуги прилягає смуга розгону: звідти вливатимуться автомобілі."),
    RoadSignInfo("5.23", "Прилягання додаткової смуги руху з правого боку", "Справа до основної смуги прилягає додаткова смуга."),
    RoadSignInfo("5.24.1", "Зміна напрямку руху на дорозі з розділювальною смугою", "Показує об’їзд закритої ділянки через розрив у розділювальній смузі на ліву проїзну частину."),
    RoadSignInfo("5.24.2", "Зміна напрямку руху на дорозі з розділювальною смугою", "Показує повернення на праву проїзну частину після об’їзду."),
    RoadSignInfo("5.25", "Смуга руху для аварійної зупинки", "Аварійна смуга (часто з піском чи гравієм) для зупинки транспорту, у якого відмовили гальма."),
    RoadSignInfo("5.26", "Місце для розвороту", "Тут можна розвернутися. Повертати ліворуч заборонено."),
    RoadSignInfo("5.27", "Зона для розвороту", "Протяжність зони, де можна розвернутися. Повертати ліворуч заборонено."),
    RoadSignInfo("5.28.1", "Напрямок руху для вантажних автомобілів", "Рекомендований напрямок для вантажівок і самохідних машин: прямо."),
    RoadSignInfo("5.28.2", "Напрямок руху для вантажних автомобілів", "Рекомендований напрямок для вантажівок: праворуч."),
    RoadSignInfo("5.28.3", "Напрямок руху для вантажних автомобілів", "Рекомендований напрямок для вантажівок: ліворуч."),
    RoadSignInfo("5.29.1", "Тупик", "Дорога без наскрізного проїзду."),
    RoadSignInfo("5.29.2", "Тупик", "Тупик на дорозі, що відходить праворуч."),
    RoadSignInfo("5.29.3", "Тупик", "Тупик на дорозі, що відходить ліворуч."),
    RoadSignInfo("5.30", "Рекомендована швидкість", "Рекомендована (не обов’язкова) швидкість. Діє до найближчого перехрестя."),
    RoadSignInfo("5.31", "Житлова зона", "В’їзд у житлову зону (розділ 26): пішоходи можуть іти проїзною частиною й мають перевагу. Швидкість — не більше 20 км/год."),
    RoadSignInfo("5.32", "Кінець житлової зони", "Виїзд із житлової зони. Виїжджаючи, ви поступаєтеся дорогою всім іншим учасникам."),
    RoadSignInfo("5.33", "Пішохідна зона", "Початок пішохідної зони: рух транспорту заборонено (крім тих, що обслуговують зону або належать її мешканцям, і водіїв з інвалідністю)."),
    RoadSignInfo("5.34", "Кінець пішохідної зони", "Закінчення пішохідної зони."),
    RoadSignInfo("5.35.1", "Пішохідний перехід", "Ставиться праворуч від дороги на ближній межі переходу. Пішоходи на переході мають перевагу."),
    RoadSignInfo("5.35.2", "Пішохідний перехід", "Ставиться ліворуч на дальній межі переходу."),
    RoadSignInfo("5.36.1", "Підземний пішохідний перехід", "Вхід у підземний перехід (праворуч)."),
    RoadSignInfo("5.36.2", "Підземний пішохідний перехід", "Вхід у підземний перехід (ліворуч)."),
    RoadSignInfo("5.37.1", "Надземний пішохідний перехід", "Вхід на надземний перехід (праворуч)."),
    RoadSignInfo("5.37.2", "Надземний пішохідний перехід", "Вхід на надземний перехід (ліворуч)."),
    RoadSignInfo("5.38", "Місце для стоянки", "Місце чи майданчик для стоянки. Таблички 7.6 показують, як ставити автомобіль, 7.4 і 7.19 — коли і на скільки."),
    RoadSignInfo("5.39", "Зона стоянки", "Зона, де стоянка дозволена на умовах, вказаних на знаку чи табличках. Діє на всю зону."),
    RoadSignInfo("5.40", "Кінець зони стоянки", "Закінчення зони стоянки."),
    RoadSignInfo("5.41.1", "Пункт зупинки автобуса", "Початок посадкового майданчика автобуса. Зупинятися ближче ніж 30 м до нього (крім маршрутних) заборонено."),
    RoadSignInfo("5.41.2", "Кінець пункту зупинки автобуса", "Кінець посадкового майданчика автобуса."),
    RoadSignInfo("5.42.1", "Пункт зупинки трамвая", "Початок посадкового майданчика трамвая. Пропустіть пасажирів, що йдуть до трамвая чи від нього."),
    RoadSignInfo("5.42.2", "Кінець пункту зупинки трамвая", "Кінець посадкового майданчика трамвая."),
    RoadSignInfo("5.43.1", "Пункт зупинки тролейбуса", "Початок посадкового майданчика тролейбуса."),
    RoadSignInfo("5.43.2", "Кінець пункту зупинки тролейбуса", "Кінець посадкового майданчика тролейбуса."),
    RoadSignInfo("5.44", "Місце зупинки таксі", "Стоянка для таксі. Іншим зупинятися тут не можна."),
    RoadSignInfo("5.45", "Початок населеного пункту", "Назва населеного пункту: тут починають діяти правила руху в населених пунктах (максимум 50 км/год)."),
    RoadSignInfo("5.46", "Кінець населеного пункту", "Тут перестають діяти правила руху в населених пунктах."),
    RoadSignInfo("5.47", "Початок населеного пункту", "Назва населеного пункту, але на цій дорозі правила руху в населених пунктах (обмеження 50 км/год) не діють."),
    RoadSignInfo("5.48", "Кінець населеного пункту", "Кінець населеного пункту, позначеного знаком 5.47."),
    RoadSignInfo("5.49", "Покажчик загальних обмежень швидкості", "Нагадує загальні обмеження швидкості в Україні: у населеному пункті, поза ним, на дорогах з розділювальною смугою і на автомагістралях."),
    RoadSignInfo("5.50", "Можливість використання дороги", "Чи відкрито гірську дорогу або перевал. Зелена табличка «Відкрито» — можна, червона «Закрито» — не можна."),
    RoadSignInfo("5.51", "Попередній покажчик напрямків", "Напрямки до населених пунктів і об’єктів на найближчому перехресті та відстань до нього. Може показувати об’їзд ділянки із заборонами 3.15–3.19."),
    RoadSignInfo("5.52", "Попередній покажчик напрямку", "Напрямок до населених пунктів на найближчому повороті."),
    RoadSignInfo("5.53", "Покажчик напрямку", "Напрямок і відстань (км) до населеного пункту. Коричневий фон — до туристичних визначних місць."),
    RoadSignInfo("5.54", "Покажчик напрямків", "Кілька напрямків руху до населених пунктів з відстанями."),
    RoadSignInfo("5.55", "Схема руху", "Маршрут руху на перехресті, де заборонені окремі маневри, або дозволені напрямки на складному перехресті."),
    RoadSignInfo("5.56", "Схема об’їзду", "Маршрут об’їзду ділянки, тимчасово закритої для руху."),
    RoadSignInfo("5.57.1", "Напрямок об’їзду", "Об’їзд тимчасово закритої ділянки: праворуч."),
    RoadSignInfo("5.57.2", "Напрямок об’їзду", "Об’їзд тимчасово закритої ділянки: ліворуч."),
    RoadSignInfo("5.57.3", "Напрямок об’їзду", "Об’їзд тимчасово закритої ділянки: на найближчому повороті праворуч."),
    RoadSignInfo("5.58.1", "Назва об’єкта", "Назва об’єкта, що не є населеним пунктом: річка, озеро, перевал, визначне місце."),
    RoadSignInfo("5.58.2", "Назва об’єкта", "Назва вулиці чи іншого об’єкта в населеному пункті."),
    RoadSignInfo("5.59", "Покажчик відстаней", "Відстані (км) до населених пунктів на маршруті."),
    RoadSignInfo("5.60", "Кілометровий знак", "Відстань (км) від початку дороги."),
    RoadSignInfo("5.61.1", "Номер маршруту", "Номер дороги (маршруту): М — міжнародна, Н — національна, Р — регіональна, Т — територіальна."),
    RoadSignInfo("5.61.2", "Номер маршруту", "Номер і напрямок дороги."),
